cd /workspace && node -e "
const fs = require('fs');

// Read the xlsx file using a simple approach
// Let's check if there's a library available
try {
  const xlsx = require('xlsx');
  const wb = xlsx.readFile('testbed/data/travel_expenses.xlsx');
  const ws = wb.Sheets[wb.SheetNames[0]];
  const data = xlsx.utils.sheet_to_json(ws);
  console.log(JSON.stringify(data, null, 2));
} catch(e) {
  console.log('xlsx not available:', e.message);
}
"

cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', JSON.stringify(tables));
" 2>/dev/null || echo "better-sqlite3 not available"

